insert into public.learning_content(id,payload,tier,published) values('linear-01','{"kind":"linear","topicLabel":"ישרים ושיפוע","grade":9,"query":"value","title":"בונים מסלול","stem":"נתון הישר y = {m}x + {b}. מהו y כאשר x = {x}?","params":{"m":2,"b":1,"x":2},"answer":5,"transfer":{"params":{"m":2,"b":1,"x":3},"query":"value","answer":7,"stem":"נתון הישר y = {m}x + {b}. מהו y כאשר x = {x}?","meaning":"אותו רעיון, נתונים אחרים: נסו קודם לדמיין את הציור בלי להציג אותו.","en":{"stem":"The line is y = {m}x + {b}. What is y when x = {x}?","meaning":"Same idea, different numbers. Picture the model before revealing it."}},"prediction":{"question":"כשמתקדמים צעד אחד ימינה, בכמה משתנה הגובה?","options":["עולה ב־2","עולה ב־1","יורד ב־2"],"correct":0},"meaning":"השיפוע הוא שינוי בגובה לכל צעד ימינה. החיתוך עם ציר y קובע מאיפה מתחילים.","rule":"y = mx + b","mediation":["מהו הגובה ההתחלתי? מצאו את החיתוך עם ציר y.","כל צעד ימינה מוסיף את השיפוע. דמיינו שני צעדים.","חברו בין הגובה בציור להצבה במשוואה."],"id":"linear-01","topic":"linear","tier":"free","level":1,"minutes":3,"summary":"השיפוע הוא שינוי בגובה לכל צעד ימינה. החיתוך עם ציר y קובע מאיפה מתחילים.","source":{"method":"original_authored","date":"2026-10-04","review":"mathematical_validator","curriculumAlignment":"suggested; teacher review required"},"en":{"title":"Build a route","topicLabel":"Lines & slope","stem":"The line is y = {m}x + {b}. What is y when x = {x}?","meaning":"Slope is the change in height for each step to the right. The y-intercept sets the starting height.","mediation":["Find the starting height on the y-axis.","Picture two steps to the right. Each adds the slope.","Connect the height in the picture to substitution in the equation."],"summary":"Slope is the change in height for each step to the right. The y-intercept sets the starting height.","rule":"y = mx + b","prediction":{"question":"For one step to the right, how much does the height change?","options":["Up by 2","Up by 1","Down by 2"],"correct":0