insert into public.learning_content(id,payload,tier,published) values('intersection-01','{"kind":"intersection","topicLabel":"משוואות ומפגשים","grade":10,"query":"intersectionX","title":"איפה נפגשים?","stem":"שני המסלולים הם y = {m}x + {b} ו־y = {n}x + {c}. באיזה x הם נפגשים?","params":{"m":2,"b":1,"n":-1,"c":7,"x":0},"answer":2,"transfer":{"params":{"m":1,"b":0,"n":-1,"c":6,"x":0},"query":"intersectionX","answer":3,"stem":"שני המסלולים הם y = {m}x + {b} ו־y = {n}x + {c}. באיזה x הם נפגשים?","meaning":"אותו רעיון, נתונים אחרים: נסו קודם לדמיין את הציור בלי להציג אותו.","en":{"stem":"The lines are y = {m}x + {b} and y = {n}x + {c}. At which x do they meet?","meaning":"Same idea, different numbers. Picture the model before revealing it."}},"prediction":{"question":"ישר עולה וישר יורד — כמה נקודות מפגש יש להם?","options":["אף אחת","אחת","שתיים"],"correct":1},"meaning":"בנקודת המפגש שני המסלולים נותנים אותו גובה. לכן משווים בין הביטויים.","rule":"mx + b = nx + c","mediation":["עקבו בעיניים אחרי כל מסלול בנפרד.","דמיינו מקום שבו שני הגבהים שווים.","השוויון בציור הופך למשוואה עם נעלם אחד."],"id":"intersection-01","topic":"intersection","tier":"free","level":1,"minutes":3,"summary":"בנקודת המפגש שני המסלולים נותנים אותו גובה. לכן משווים בין הביטויים.","source":{"method":"original_authored","date":"2026-10-04","review":"mathematical_validator","curriculumAlignment":"suggested; teacher review required"},"en":{"title":"Where do they meet?","topicLabel":"Equations & intersections","stem":"The lines are y = {m}x + {b} and y = {n}x + {c}. At which x do they meet?","meaning":"At an intersection both lines have the same height, so their expressions are equal.","mediation":["Follow each line separately.","Picture the location where their heights match.","Turn that visual match into an equation with one unknown."],"summary":"At an intersection both lines have the same height, so their expressions are equal.","rule":"mx + b = nx + c","prediction":{"question":"One line rises and the other falls. How many intersections are there?","options":["None","One","Two"],"correct":1}}}'::jsonb,'free',true) on conflict(id) do update set payload=excluded.payload,tier=excluded.tier,published=true,updated_at=now();
