insert into public.learning_content(id,payload,tier,published) values('triangle-01','{"kind":"triangle","topicLabel":"משולשים ופיתגורס","grade":10,"query":"hypotenuse","title":"בונים קיצור דרך","stem":"במשולש ישר־זווית אורכי הניצבים הם {a} ו־{b}. מהו אורך היתר?","params":{"a":3,"b":4,"x":0},"answer":5,"transfer":{"params":{"a":6,"b":8,"x":0},"query":"hypotenuse","answer":10,"stem":"במשולש ישר־זווית אורכי הניצבים הם {a} ו־{b}. מהו אורך היתר?","meaning":"אותו רעיון, נתונים אחרים: נסו קודם לדמיין את הציור בלי להציג אותו.","en":{"stem":"A right triangle has legs of length {a} and {b}. How long is the hypotenuse?","meaning":"Same idea, different numbers. Picture the model before revealing it."}},"prediction":{"question":"היתר הוא הצלע שמול הזווית הישרה. מה נכון?","options":["קצר מכל ניצב","שווה תמיד לניצב","ארוך מכל ניצב"],"correct":2},"meaning":"היתר מחבר את קצות שני הניצבים. פיתגורס מקשר בין ריבועי האורכים.","rule":"c² = a² + b²","mediation":["זהו קודם את הזווית הישרה ואת הצלע שמולה.","דמיינו ריבוע על כל צלע: איזה שטח הוא סכום האחרים?","מצאו את ריבוע היתר, ואז את האורך עצמו."],"id":"triangle-01","topic":"triangle","tier":"free","level":1,"minutes":3,"summary":"היתר מחבר את קצות שני הניצבים. פיתגורס מקשר בין ריבועי האורכים.","source":{"method":"original_authored","date":"2026-10-04","review":"mathematical_validator","curriculumAlignment":"suggested; teacher review required"},"en":{"title":"Find the shortcut","topicLabel":"Triangles & Pythagoras","stem":"A right triangle has legs of length {a} and {b}. How long is the hypotenuse?","meaning":"The hypotenuse connects the ends of the two legs. Pythagoras relates the squared lengths.","mediation":["Locate the right angle and the side opposite it.","Picture a square on each side. Which area equals the other two added together?","Find the square of the hypotenuse, then its length."],"summary":"The hypotenuse connects the ends of the two legs. Pythagoras relates the squared lengths.","rule":"c² = a² + b²","prediction":{"questio